def collect(s):
    s = dict(s)
    primary = any(m in ["CNC", "Hydraulics", "Conveyor belt"] for m in s["machines"])
    if s["id"].startswith("RUB-") or s["id"].startswith("FAIL-SKF"):
        primary = True
    s.update(retrieved_date="2026-10-06", language="en", collection_scope="primary" if primary else "supplementary_previous_scope", model_match_status="equipment_categories_selected_exact_models_unspecified", instructor_review_status="pending", rights_status="public_access_no_AI_reuse_permission_verified", external_inference_allowed=False, fine_tuning_allowed=False, redistribution_allowed=False, generation_approved=False, download_status="reference_link_only")
    if "file" not in s:
        return s
    path = ROOT / s["file"]
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        if path.exists():
            data = path.read_bytes()
            s["download_status"] = "existing_file_verified"
        else:
            req = Request(s["url"], headers={"User-Agent":"PS015 research source collector/1.0"})
            with urlopen(req, timeout=45) as response:
                data = response.read(35 * 1024 * 1024 + 1)
                s["resolved_url"] = response.url
                s["http_last_modified"] = response.headers.get("Last-Modified")
                s["http_content_type"] = response.headers.get("Content-Type")
            if len(data) > 35 * 1024 * 1024:
                raise ValueError("Reference exceeds the 35 MiB collection bound")
            if not data.lstrip().startswith(b"%PDF-"):
                raise ValueError("Response is not a PDF")
            path.write_bytes(data)
            s["download_status"] = "downloaded"
        s["sha256"] = hashlib.sha256(data).hexdigest()
        s["bytes"] = len(data)
    except Exception as exc:
        s["download_status"] = "failed"
        s["download_error"] = str(exc)
    return s

def main():
    ROOT.mkdir(parents=True, exist_ok=True)
    with ThreadPoolExecutor(max_workers=4) as pool:
        sources = list(pool.map(collect, SOURCES))
    manifest = dict(schema_version="ps015-source-library/1.0", collected_date="2026-10-06", updated_at=datetime.now(timezone.utc).isoformat(), focus_machines=["CNC", "Hydraulics", "Conveyor belt"], equipment_selection_status="categories_selected_exact_models_unspecified", sources=sources)
    (ROOT / "source-register.json").write_text(json.dumps(manifest, indent=2, ensure_ascii=False)+"\n", encoding="utf-8")
    for s in sources:
        print(f'{s["id"]}: {s["download_status"]}' + (f' ({s["bytes"]} bytes)' if "bytes" in s else "") + (f': {s["download_error"]}' if "download_error" in s else ""))

if __name__ == "__main__":
    main()
